inputs = ['xdcahh', 'dfx', 'hdg', 'ddkkb', 'ijihbx']
outputs = ['xbecahh', 'befx', 'hbeg', 'vuukkb', 'ijihbx']

# Analyze each changed pair
pairs = [(0, 'xdcahh', 'xbecahh'), (1, 'dfx', 'befx'), (2, 'hdg', 'hbeg'), (3, 'ddkkb', 'vuukkb')]

for idx, inp, out in pairs:
    print(f"Pair {idx}: '{inp}' -> '{out}'")

    # Find differences character by character
    min_len = min(len(inp), len(out))
    diff_positions = []
    for i in range(min_len):
        if inp[i] != out[i]:
            diff_positions.append((i, inp[i], out[i]))

    # Check if we have length differences
    if len(inp) != len(out):
        if len(inp) > len(out):
            # String got shorter
            for i in range(min_len, len(inp)):
                diff_positions.append((i, inp[i], None))
        else:
            # String got longer  
            for i in range(min_len, len(out)):
                diff_positions.append((i, None, out[i]))

    print(f"  Differences: {diff_positions}")
    print()

